    body: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><title>Mailroom</title><rect width=\"64\" height=\"64\" rx=\"14\" fill=\"#2f5d50\"/><path d=\"M14 22h36v22a4 4 0 0 1-4 4H18a4 4 0 0 1-4-4z\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linejoin=\"round\"/><path d=\"m14 24 18 13 18-13\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linejoin=\"round\"/></svg>\n",
